//! Validated integer programs used during dataset construction.
//! Programs are generated by [`super::scheduler`].
use core::fmt;

/// Return the multiplier for IMUL_RCP. Zero and powers of two are not divisors
/// emitted by the superscalar generator and are rejected at this boundary.
pub fn reciprocal(divisor: u32) -> Option<u64> {
    if divisor == 0 || divisor.is_power_of_two() {
        return None;
    }
    let shift = 32 - divisor.leading_zeros();
    let divisor = u64::from(divisor);
    let numerator = 1u64 << 63;
    // Split the exact wide quotient into two native-width divisions. The
    // remainder is below 2^32 and shift <= 32, so its left shift cannot overflow.
    Some(((numerator / divisor) << shift) + (((numerator % divisor) << shift) / divisor))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InvalidProgram;
impl fmt::Display for InvalidProgram {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("invalid superscalar program")
    }
}
impl std::error::Error for InvalidProgram {}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub(crate) enum Operation {
    Sub = 0,
    Xor = 1,
    AddShift = 2,
    Mul = 3,
    Rotate = 4,
    AddConstant = 5,
    XorConstant = 6,
    MulHigh = 7,
    SignedMulHigh = 8,
    MulReciprocal = 9,
}

#[derive(Clone, Debug)]
#[repr(C)]
pub(crate) struct Packed {
    pub(crate) immediate: u32,
    pub(crate) opcode: Operation,
    pub(crate) dst: u8,
    pub(crate) src: u8,
    pub(crate) shift: u8,
}
impl Packed {
    pub(crate) fn signed_immediate(&self) -> u64 {
        self.immediate as i32 as i64 as u64
    }
}
// The x86-64 assembly interpreter consumes this exact byte layout.
const _: () = {
    assert!(std::mem::size_of::<Packed>() == 8);
    assert!(std::mem::offset_of!(Packed, immediate) == 0);
    assert!(std::mem::offset_of!(Packed, opcode) == 4);
    assert!(std::mem::offset_of!(Packed, dst) == 5);
    assert!(std::mem::offset_of!(Packed, src) == 6);
    assert!(std::mem::offset_of!(Packed, shift) == 7);
};
#[derive(Clone, Debug)]
pub struct Program {
    address_register: usize,
    packed: Box<[Packed]>,
    reciprocals: Box<[u64]>,
}

impl Program {
    /// Decode the upstream 8-byte instruction encoding. If reciprocals is
    /// present, IMUL_RCP immediates index that table; otherwise they are divisors.
    /// Invalid input is rejected before any register state can be modified.
    pub fn decode(
        bytes: &[u8],
        address_register: u8,
        reciprocals: Option<&[u64]>,
    ) -> Result<Self, InvalidProgram> {
        if bytes.is_empty()
            || !bytes.len().is_multiple_of(8)
            || bytes.len() / 8 > 512
            || address_register >= 8
        {
            return Err(InvalidProgram);
        }
        let mut packed = Vec::with_capacity(bytes.len() / 8);
        let mut multipliers = Vec::new();
        for bytes in bytes.as_chunks::<8>().0 {
            let dst = bytes[1];
            let src = bytes[2];
            if dst >= 8 || src >= 8 {
                return Err(InvalidProgram);
            }
            let immediate = u32::from_le_bytes(bytes[4..].try_into().unwrap());
            let (opcode, immediate, shift) = match bytes[0] {
                0 => (Operation::Sub, 0, 0),
                1 => (Operation::Xor, 0, 0),
                2 => (Operation::AddShift, 0, (bytes[3] >> 2) & 3),
                3 => (Operation::Mul, 0, 0),
                4 if immediate < 64 => (Operation::Rotate, 0, immediate as u8),
                5 | 7 | 9 => (Operation::AddConstant, immediate, 0),
                6 | 8 | 10 => (Operation::XorConstant, immediate, 0),
                11 => (Operation::MulHigh, 0, 0),
                12 => (Operation::SignedMulHigh, 0, 0),
                13 => {
                    let value = match reciprocals {
                        Some(table) => *table.get(immediate as usize).ok_or(InvalidProgram)?,
                        None => reciprocal(immediate).ok_or(InvalidProgram)?,
                    };
                    let index = multipliers.len() as u32;
                    multipliers.push(value);
                    (Operation::MulReciprocal, index, 0)
                }
                _ => return Err(InvalidProgram),
            };
            packed.push(Packed {
                immediate,
                opcode,
                dst,
                src,
                shift,
            });
        }
        Ok(Self {
            packed: packed.into_boxed_slice(),
            reciprocals: multipliers.into_boxed_slice(),
            address_register: usize::from(address_register),
        })
    }

    /// JITs and the portable executor share the same eight-byte instructions.
    /// Keeping expanded operands would add 32 bytes per instruction on 64-bit
    /// targets for the lifetime of every cache.
    pub(crate) fn instructions(&self) -> &[Packed] {
        &self.packed
    }
    pub(crate) fn multiplier(&self, instruction: &Packed) -> u64 {
        self.reciprocals[instruction.immediate as usize]
    }

    #[cfg(target_arch = "x86_64")]
    pub(crate) fn packed(&self) -> (&[Packed], &[u64]) {
        (&self.packed, &self.reciprocals)
    }
    pub fn address_register(&self) -> usize {
        self.address_register
    }

    pub fn execute(&self, registers: &mut [u64; 8]) {
        // Eight-byte instructions keep all eight programs near L1 capacity.
        // Masks expose decoder invariants to the optimizer without unsafe access.
        for instruction in &self.packed {
            let dst = (instruction.dst & 7) as usize;
            let src = (instruction.src & 7) as usize;
            let a = registers[dst];
            let b = registers[src];
            registers[dst] = match instruction.opcode {
                Operation::Sub => a.wrapping_sub(b),
                Operation::Xor => a ^ b,
                Operation::AddShift => a.wrapping_add(b << (instruction.shift & 3)),
                Operation::Mul => a.wrapping_mul(b),
                Operation::Rotate => a.rotate_right(instruction.shift as u32),
                Operation::AddConstant => a.wrapping_add(instruction.signed_immediate()),
                Operation::XorConstant => a ^ instruction.signed_immediate(),
                Operation::MulHigh => ((u128::from(a) * u128::from(b)) >> 64) as u64,
                Operation::SignedMulHigh => {
                    ((i128::from(a as i64) * i128::from(b as i64)) >> 64) as u64
                }
                Operation::MulReciprocal => {
                    a.wrapping_mul(self.reciprocals[instruction.immediate as usize])
                }
            };
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn packed_operands_preserve_signed_immediates_and_table_multipliers() {
        let bytes = [
            [5, 7, 1, 0, 0, 0, 0, 0x80],
            [10, 6, 2, 0, 0xff, 0xff, 0xff, 0xff],
            [2, 5, 3, 0xff, 0, 0, 0, 0],
            [4, 4, 0, 0, 63, 0, 0, 0],
            [13, 3, 7, 0, 1, 0, 0, 0],
            [13, 2, 6, 0, 0, 0, 0, 0],
        ];
        let multiplier = 0xfedcba9876543210;
        let program = Program::decode(bytes.as_flattened(), 5, Some(&[0, multiplier])).unwrap();
        let packed = program.instructions();
        assert_eq!(packed.len(), bytes.len());
        for (instruction, raw) in packed.iter().zip(bytes) {
            assert_eq!(instruction.dst, raw[1]);
            assert_eq!(instruction.src, raw[2]);
        }
        assert_eq!(packed[0].opcode, Operation::AddConstant);
        assert_eq!(packed[0].signed_immediate(), 0xffffffff80000000);
        assert_eq!(packed[1].opcode, Operation::XorConstant);
        assert_eq!(packed[1].signed_immediate(), u64::MAX);
        assert_eq!(packed[2].opcode, Operation::AddShift);
        assert_eq!(packed[2].shift, 3);
        assert_eq!(packed[3].opcode, Operation::Rotate);
        assert_eq!(packed[3].shift, 63);
        assert_eq!(packed[4].opcode, Operation::MulReciprocal);
        assert_eq!(program.multiplier(&packed[4]), multiplier);
        assert_eq!(program.multiplier(&packed[5]), 0);
        assert_eq!(program.address_register(), 5);
    }

    #[test]
    fn reciprocal_vectors_and_invalid_divisors() {
        for (divisor, expected) in [
            (3, 12297829382473034410),
            (13, 11351842506898185609),
            (33, 17887751829051686415),
            (65537, 18446462603027742720),
            (15000001, 10316166306300415204),
            (3845182035, 10302264209224146340),
            (u32::MAX, 9223372039002259456),
        ] {
            assert_eq!(reciprocal(divisor), Some(expected));
        }
        assert_eq!(reciprocal(0), None);
        for bit in 0..32 {
            assert_eq!(reciprocal(1 << bit), None);
        }
    }

    #[test]
    fn malformed_programs_are_rejected() {
        for bytes in [
            &[][..],
            &[0; 7][..],
            &[0; 4097][..],
            &[14, 0, 0, 0, 0, 0, 0, 0][..],
            &[0, 8, 0, 0, 0, 0, 0, 0][..],
            &[0, 0, 8, 0, 0, 0, 0, 0][..],
            &[4, 0, 0, 0, 64, 0, 0, 0][..],
            &[13, 0, 0, 0, 0, 0, 0, 0][..],
            &[13, 0, 0, 0, 2, 0, 0, 0][..],
        ] {
            assert!(Program::decode(bytes, 0, None).is_err());
        }
        assert!(Program::decode(&[0; 8], 8, None).is_err());
        assert!(Program::decode(&[13, 0, 0, 0, 1, 0, 0, 0], 0, Some(&[7])).is_err());
    }
}
